mapper.select:
SELECT *
FROM billing_period
WHERE account_id = #{accountId}
  AND period_start = #{periodStart}
LIMIT 1

SELECT COALESCE(SUM(usage_bytes - billed_bytes), 0)
FROM tunnel_usage_window
WHERE account_id = #{accountId}
  AND window_start >= #{periodStart}
  AND window_start < #{periodEnd}
  AND usage_bytes > billed_bytes

mapper.update:
UPDATE tunnel_usage_window
SET billed_bytes = #{expectedUsageBytes}
WHERE _id = #{usageWindowId}
  AND billed_bytes = #{expectedBilledBytes}
  AND usage_bytes = #{expectedUsageBytes}

UPDATE billing_period
SET billed_bytes = billed_bytes + #{usageBytes}
WHERE account_id = #{accountId}
  AND period_start = #{periodStart}
